# ---------------------------------------------------------------- D-BD03 미술관 매칭 (조건 넷, 120가지 전수 조사)
MUS = {'가': (120, 8000, 40), '나': (80, 12000, 25), '다': (60, 3000, 70), '라': (150, 6000, 20), '마': (40, 5000, 50)}   # 관람객(만 명), 소장품(점), 무료 관람 비율(%)
paid = lambda k: F(MUS[k][0] * (100 - MUS[k][2]), 100); free = lambda k: F(MUS[k][0] * MUS[k][2], 100)
unique_max({k: paid(k) for k in MUS}, 'D-BD03'); unique_max({k: v[1] for k, v in MUS.items()}, 'D-BD03'); unique_max({k: free(k) for k in MUS}, 'D-BD03')
