CON3 = [lambda m: paid(m['갑']) == max(paid(k) for k in MUS), lambda m: MUS[m['을']][1] == max(v[1] for v in MUS.values()), lambda m: free(m['병']) == max(free(k) for k in MUS), lambda m: MUS[m['정']][0] > MUS[m['무']][0]]
def sols3(cs): return [m for m in (dict(zip(NM, pm)) for pm in itertools.permutations(MUS)) if all(c(m) for c in cs)]
S3 = sols3(CON3)
check(S3 == [{'갑': '라', '을': '나', '병': '가', '정': '다', '무': '마'}], f'D-BD03 {S3}')
for i in range(4): check(len(sols3([c for j, c in enumerate(CON3) if j != i])) > 1, f'D-BD03 condition {i} needed')
check([paid(k) for k in MUS] == [72, 60, 18, 120, 20] and [free(k) for k in MUS] == [48, 20, 42, 30, 20], 'D-BD03 explanation numbers')
key3 = ', '.join(S3[0][c] for c in NM)
opts3 = ['가, 나, 라, 다, 마', '라, 나, 다, 가, 마', '라, 가, 나, 다, 마', key3, '라, 나, 가, 마, 다']
